function resize(){width=stage.clientWidth;height=stage.clientHeight;const dpr=Math.min(devicePixelRatio||1,2);for(const c of [world,actors]){c.width=Math.round(width*dpr);c.height=Math.round(height*dpr);c.getContext('2d').setTransform(dpr,0,0,dpr,0,0);c.getContext('2d').imageSmoothingEnabled=false;}const old=game;game=new Game(width,height,measureBlocks());game.blocks.forEach(b=>b.dead=!!$(`[data-block="${b.id}"]`)?.classList.contains('destroyed'));if(old&&playing){game.score=old.score;game.hp=old.hp;game.destroyed=old.destroyed;game.state=old.state;}drawBackground();}
function render(next=section){clearTimeout(overTimer);buildTimers.forEach(clearTimeout);buildTimers=[];keys={};section=pages[next]?next:'perfil';game=null;lastProgress='';visited.add(section);content.className='content is-'+section;content.innerHTML=pages[section]();$('#gameover').hidden=true;$('#path').textContent='~/'+section;$$('.nav').forEach(b=>{const on=b.dataset.section===section;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const blocks=$$('.block');blocks.forEach((b,i)=>{b.style.setProperty('--delay',`${reduced?0:i*.13}s`);});buildingUntil=performance.now()+(reduced?30:blocks.length*130+750);$('#status').textContent='ensamblando '+section+'…';progress(0,blocks.length);blocks.forEach((b,i)=>buildTimers.push(setTimeout(()=>{tone(180+i*35,.035);progress(i+1,blocks.length);},reduced?10:i*130+750)));buildTimers.push(setTimeout(()=>{resize();$('#status').textContent=playing?'Protege la foto. Los otros constructores no están de tu lado.':'listo. explora las secciones o pulsa ▶ para jugar.';if(playing)updateHUD();},reduced?30:blocks.length*130+800));resize();if(playing)announce('Nuevo escenario. Tu foto sigue siendo el bloque crítico.');}
