function rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function beam(x,y,w){rect(bg,x,y,w,12,'#2a3930');rect(bg,x,y+2,w,2,'#536356');rect(bg,x,y+10,w,3,'#050c08');for(let k=x;k<x+w;k+=22){bg.strokeStyle='#131e16';bg.lineWidth=3;bg.beginPath();bg.moveTo(k,y+3);bg.lineTo(k+17,y+10);bg.moveTo(k+17,y+3);bg.lineTo(k,y+10);bg.stroke();rect(bg,k+2,y+2,2,2,'#81917c');}}
