function drawBackground(){bg.clearRect(0,0,width,height);if(!game)return;for(const x of [16,width-26]){rect(bg,x,65,9,height-65,'#1b2a20');rect(bg,x+2,65,2,height-65,'#344338');for(let y=70;y<height;y+=41){bg.strokeStyle='#2c3d30';bg.lineWidth=3;bg.beginPath();bg.moveTo(x,y);bg.lineTo(x+14,y+36);bg.moveTo(x+14,y);bg.lineTo(x,y+36);bg.stroke();}}beam(0,height*.15,width*.29);beam(width*.64,height*.13,width*.36);rect(bg,0,height*.16,width,1,'#1b2b1e');for(let x=25;x<width;x+=120){rect(bg,x,height*.16,3,height*.55,'#1b2b1e66');}for(const l of game.ladders)ladder(l);for(const b of game.blocks){if(!b.dead)beam(b.x-4,b.y+b.h+4,b.w+8);}for(const c of game.crates)crate(c);beam(0,game.floor,width);for(let x=0;x<width;x+=55){rect(bg,x,game.floor+13,7,70,'#26372b');bg.strokeStyle='#1b2b20';bg.lineWidth=4;bg.beginPath();bg.moveTo(x+8,game.floor+20);bg.lineTo(x+48,height);bg.moveTo(x+48,game.floor+20);bg.lineTo(x+8,height);bg.stroke();}for(let x=40;x<width;x+=180){rect(bg,x,game.floor-8,4,8,'#f5c86a');rect(bg,x-2,game.floor-10,8,3,'#ffdf8a');}bg.strokeStyle='#bb8c37';bg.lineWidth=2;const crane=width*.51;bg.beginPath();bg.moveTo(crane,0);bg.lineTo(crane,65);bg.stroke();rect(bg,crane-7,65,14,11,'#c39746');bg.strokeStyle='#97733c';bg.lineWidth=4;bg.beginPath();bg.moveTo(crane,77);bg.lineTo(crane-20,98);bg.lineTo(crane-16,108);bg.moveTo(crane,77);bg.lineTo(crane+20,98);bg.lineTo(crane+16,108);bg.stroke();}
function worker(c,x,y,{dir=1,walk=0,player=false,enemy=false,stun=0,swing=0,carry=false}={}){c.save();c.translate(Math.round(x+12),Math.round(y+40));c.scale(dir,1);if(stun){c.globalAlpha=.3+.3*Math.sin(performance.now()/100);}const leg=Math.sin(walk)*3;rect(c,-8,-14,7,11+leg,'#335e6a');rect(c,2,-14,7,11-leg,'#426c7b');rect(c,-10,-4+leg,10,4,'#8a6435');rect(c,1,-4-leg,11,4,'#8a6435');rect(c,-8,-28,17,16,enemy?'#a55f49':'#cd8246');rect(c,-5,-26,5,12,'#e2a060');rect(c,-8,-37,17,13,'#efbc85');rect(c,5,-34,6,6,'#e6ae76');rect(c,-9,-39,20,5,enemy?'#c8a171':'#f6c858');rect(c,-6,-43,13,8,enemy?'#b88a55':'#edb942');rect(c,-2,-44,4,8,enemy?'#d2b086':'#ffe08d');rect(c,-11,-36,24,3,enemy?'#d8b48a':'#ffdb76');rect(c,1,-34,7,5,'#1b2622');rect(c,3,-33,3,2,'#c8e3c3');rect(c,-6,-34,5,5,'#1b2622');rect(c,-4,-33,2,2,'#d7e7cc');rect(c,-1,-33,3,1,'#16221b');rect(c,-9,-25,5,11,'#e6a973');if(carry){rect(c,8,-27,5,10,'#e5ad75');rect(c,12,-34,24,21,'#235b38');rect(c,14,-32,20,17,'#3f8852');rect(c,21,-28,5,7,'#90dba2');}else if(player||enemy){c.save();c.translate(8,-24);if(swing>0)c.rotate(-1.8+Math.sin(swing/.23*Math.PI)*2.9);else c.rotate(-.3);rect(c,0,-2,9,5,'#f3be84');rect(c,7,-23,4,26,'#b38a51');rect(c,2,-27,18,10,'#758a82');rect(c,3,-27,16,3,'#c6d4c8');rect(c,17,-25,4,7,'#4b6157');c.restore();}else rect(c,8,-25,4,11,'#edb17d');if(player){rect(c,-9,-59,19,3,'#88fdb9');c.fillStyle='#88fdb9';c.font='8px monospace';c.textAlign='center';c.fillText('TÚ',0,-64);c.beginPath();c.moveTo(-4,-54);c.lineTo(4,-54);c.lineTo(0,-50);c.fill();}c.restore();}
function frame(t){const dt=Math.min((t-last)/1000||.016,.035);last=t;ctx.clearRect(0,0,width,height);if(game){if(playing&&!document.hidden&&!$('dialog[open]')){game.step(dt,keys);if(keys.jump)keys.jump=false;for(const ev of game.events){if(ev.type==='destroy'){const el=$(`[data-block="${ev.id}"]`);el?.classList.add('destroyed');drawBackground();tone(160,.1,'sawtooth');$('#status').textContent='bloque destruido. +100 pts';}if(ev.type==='enemy'){tone(430,.08);$('#status').textContent='constructor aturdido. +50 pts';}if(ev.type==='hurt'){tone(90,.15,'sawtooth');announce('¡Cuidado con los constructores! Usa E para defenderte.');}if(ev.type==='jump')tone(300,.05,'sine');if(ev.type==='swing')tone(120,.03);if(ev.type==='over')gameOver(ev.reason);}game.events=[];updateHUD();}const p=game.player;if(playing){for(const e of game.enemies)worker(ctx,e.x,e.y,{dir:e.dir,walk:t/100,enemy:true,stun:e.stun});if(p.hit===0||Math.floor(t/90)%2===0)worker(ctx,p.x,p.y,{dir:p.dir,walk:p.vx?t/90:0,player:true,swing:p.swing});}else{const moving=(!reduced||t<buildingUntil);for(let i=0;i<4;i++){const travel=moving?Math.sin(t/4000+i*2)*width*.05:0;const x=width*(.07+i*.26)+travel;worker(ctx,x,game.floor-40,{dir:i%2?-1:1,walk:moving?t/150+i:0,carry:i===0||i===3});}const top=game.blocks.find(b=>b.id==='identity'||b.id==='career'||b.id==='contact');if(top)worker(ctx,top.x+top.w-18,top.y-42,{dir:-1,walk:0,carry:true});}for(const a of game.particles)rect(ctx,a.x,a.y,a.size,a.size,a.color);}raf=requestAnimationFrame(frame);}
