window.addEventListener('keydown',e=>{if($('dialog[open]'))return;if(e.code==='Escape'&&playing){stop();return;}if(!playing||!keymap[e.code])return;if(e.target.closest('button,a')&&e.code==='Space')return;e.preventDefault();if(e.repeat&&e.code==='Space')return;keys[keymap[e.code]]=true;});window.addEventListener('keyup',e=>{if(keymap[e.code])keys[keymap[e.code]]=false;});window.addEventListener('blur',()=>keys={});document.addEventListener('visibilitychange',()=>keys={});$$('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[keymap[b.dataset.key]]=true;});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[keymap[b.dataset.key]]=false);});let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{keys={};resize();},150);});render();raf=requestAnimationFrame(frame);
